/**
 * Cloudflare Workers entry point (wrangler.jsonc "main"). It wraps the .open-next/worker.js
 * generated by @opennextjs/cloudflare for two things the generated file does not do:
 *
 * 1. fetch: every HTML response gets a per-request script nonce in place of the static
 *    script-src 'unsafe-inline' (lib/csp-nonce.ts). Next 16's proxy cannot run on OpenNext, so
 *    the nonce is added here, after rendering. Static assets (/_next/static/*, public/) are
 *    served by Workers Assets before this runs and carry no CSP.
 * 2. scheduled: the handler called by Cron Triggers, replacing Vercel Cron (the crons in
 *    vercel.json). The cron routes are GETs protected by Bearer CRON_SECRET, so the Worker builds
 *    the same request internally and passes it to the fetch handler. Set CRON_SECRET with
 *    `wrangler secret put CRON_SECRET`.
 *
 * lib/worker-entry.test.ts loads this file with a fake generated worker and checks both the
 * wrangler "main" and the nonce. https://opennext.js.org/cloudflare/howtos/custom-worker
 *
 * .open-next/ is build output and is in .gitignore. This file is kept outside tsconfig (plain JS)
 * so that the pre-build type check does not try to resolve imports that have not been generated
 * yet. wrangler's bundler compiles the TypeScript import below.
 */
import openNextHandler from "./.open-next/worker.js";
import { applyScriptNonce } from "./lib/csp-nonce.ts";

export { DOQueueHandler } from "./.open-next/worker.js";
export { DOShardedTagCache } from "./.open-next/worker.js";
export { BucketCachePurge } from "./.open-next/worker.js";

// Keep this in sync with triggers.crons in wrangler.jsonc.
const CRON_PATHS = {
  "0 21 * * *": "/api/cron/daily-digest", // JST 06:00
  "0 4 * * *": "/api/cron/cleanup",
};

const worker = {
  async fetch(request, env, ctx) {
    const response = await openNextHandler.fetch(request, env, ctx);
    return applyScriptNonce(response);
  },

  async scheduled(controller, env, ctx) {
    const path = CRON_PATHS[controller.cron];
    if (!path) {
      console.error(`[cron] unknown schedule: ${controller.cron}`);
      return;
    }
    const request = new Request(`https://ai-news-feed-app.saitotakuya0719.workers.dev${path}`, {
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(
      openNextHandler.fetch(request, env, ctx).then(
        (res) => console.log(`[cron] ${path} -> ${res.status}`),
        (err) => console.error(`[cron] ${path} failed`, err),
      ),
    );
  },
};

export default worker;
